Contract AutomatedTellerMachineSystem::inputPassword(password:Integer): Boolean {
          definition:
          inputPassword:Integer = password, card:BankCard = InputCard

            precondition:
          InputCard.oclIsUndefined() = bool, CardIDValidated = true, inputPassword = card.Password, card.CardStatus = CardStatus.NORMAL

            postcondition:
          let isPasswordValid:Boolean = if inputPassword = card.Password then true else false endif, result = isPasswordValid and card.oclIsNew()

        }
